240	  /* ---------- 顶部数据源 ---------- */
241	  $('#sources').innerHTML = [
242	    ['赛狐 ERP','包裹主干 · '+k.total_orders+' 单'],
243	    ['Temu 库存','货号×库存 · '+D.inventory.codes_indexed],
244	    ['海外仓 WMS','商品主数据 · '+D.inventory.wms_master_count],
245	  ].map(([a,b])=>`<div class="src"><span class="dot"></span><b>${a}</b><span class="c">${esc(b)}</span></div>`).join('');
246	  $('#srcName').textContent = D.meta.source;
247	  $('#snapTime').textContent = D.meta.reference_now||'—';
248	
249	  /* ---------- AI 摘要 ---------- */
250	  const critCombo = O.filter(o=>o.anomalies.includes('stuck_virtual')&&o.anomalies.includes('no_channel'));
251	  const aiOk = k.actionable===0;
252	  const dueSoon = ac.due_soon||0;
253	  const aiHtml = `哨兵扫描 <b class="ok">${k.total_orders}</b> 个订单（${k.platforms} 平台 / ${k.shops} 店铺，赛狐已聚合），`+
254	    `其中 <span class="ok">${k.shipped}</span> 单已发货、当日发货率 <span class="ok">${ls.within24_pct}%</span>，运营总体健康。`+
255	    ` 需你关注：<span class="g">${k.pending}</span> 单待处理中有 <b>${k.actionable}</b> 单需立即动手`+
256	    (dueSoon?`（<span class="g">${dueSoon}</span> 单 24h 内到期）`:'')+
257	    (critCombo.length?`，其中 <b>${critCombo.length}</b> 单同时命中「卡虚拟仓＋缺渠道」将无法出库`:'')+
258	    `；库存侧发现 <b>${D.inventory.temu_zero_stock.length}</b> 个 Temu 断货货号需补货。`;
259	  $('#ai').className='ai panel'+(aiOk?' ok':'');
260	  $('#ai').innerHTML = `<div class="ic">${aiOk?'✅':'🧭'}</div><div class="txt">${aiHtml}</div>`;
261	
262	  /* ---------- KPI ---------- */
263	  const kpis=[
264	    {l:'订单总数',v:k.total_orders,s:`${k.platforms} 平台 · ${k.shops} 店铺`,c:'',sp:'📦'},
265	    {l:'待处理',v:k.pending,s:'尚未发货',c:'warn',sp:'⏳'},
266	    {l:'需立即处理',v:k.actionable,s:'命中可执行异常',c:k.actionable?'crit':'good',sp:'🚨'},
267	    {l:'当日发货率',v:ls.within24_pct+'%',s:`中位 ${ls.p50_h}h · P90 ${ls.p90_h}h`,c:'good',sp:'⚡'},
268	    {l:'断货货号',v:D.inventory.temu_zero_stock.length,s:'Temu 库存=0',c:D.inventory.temu_zero_stock.length?'crit':'good',sp:'🛒'},
269	    {l:'已作废',v:k.void,s:'不纳入履约',c:'',sp:'🗑️'},
270	  ];
271	  $('#kpis').innerHTML=kpis.map(x=>`<div class="kpi panel ${x.c}"><span class="spark">${x.sp}</span><div class="k-l">${x.l}</div><div class="k-v">${x.v}</div><div class="k-s">${esc(x.s)}</div></div>`).join('');
272	
273	  /* ---------- 异常预警 ---------- */
274	  const tier=(w)=> w>=90?'crit': w>=40?'warn':'info';
275	  const anomOrder=Object.keys(D.rules).sort((a,b)=>D.rules[b].weight-D.rules[a].weight);
276	  let activeAnom=null;
277	  function renderAnom(){
278	    $('#anom').innerHTML=anomOrder.map(t=>{
279	      const r=D.rules[t], c=ac[t]||0;
280	      return `<div class="arow ${tier(r.weight)} ${c?'':'zero'} ${activeAnom===t?'active':''}" data-a="${t}">
281	        <span class="ai-ic">${r.icon}</span>
282	        <div><div class="a-name">${esc(r.name)}</div><div class="a-desc">${esc(r.desc)}</div></div>
283	        <div class="a-cnt">${c}</div></div>`;
284	    }).join('');
285	    document.querySelectorAll('.arow').forEach(el=>el.onclick=()=>{
286	      const t=el.dataset.a; activeAnom=(activeAnom===t)?null:t; renderAnom(); apply();
287	    });
288	  }
289	  $('#anomTotal').textContent=`命中 ${Object.values(ac).reduce((a,b)=>a+b,0)} 项`;
290	  renderAnom();
291	
292	  /* ---------- 库存联动 ---------- */
293	  const zero=D.inventory.temu_zero_stock;
294	  const linkedZero=O.filter(o=>o.matched_code && (o.temu_stock!=null&&o.temu_stock<=0) && o.state==='pending');
295	  $('#invN').textContent=`索引 ${D.inventory.codes_indexed} 货号`;
296	  $('#inv').innerHTML=
297	    `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:9px;">
298	       ${zero.map(c=>`<span class="tg crit mono" style="font-size:.72rem;padding:4px 9px;">🛒 ${esc(c)} · 库存0</span>`).join('')||'<span style="color:var(--ink-3)">暂无断货</span>'}
299	     </div>
